# owner: platform
"""Plain-text absence notices for parents."""

from rosterkit.errors import NoticeError

def _absent_days(student, marks):
    days = set()
    for mark in marks:
        if mark.student_id != student.student_id:
            raise NoticeError(f"foreign mark: {mark}")
        if mark.status == "absent":
            days.add(mark.day)
    return sorted(days)

def _build_text(student, days):
    name = f"{student.first_name} {student.last_name}"
    noun = "day" if len(days) == 1 else "days"
    listed = ", ".join(item.isoformat() for item in days)
    return (
        f"{name} missed {len(days)} {noun} of "
        f"school: {listed}."
    )

# ---
def absence_notice(student, marks):
    """Short notice naming the absent days in date order."""
    days = _absent_days(student, marks)
    if not days:
        raise NoticeError(
            f"no absences: {student.student_id}"
        )
    return _build_text(student, days)
